using namespace std;
​
const int MAX_COORD = 201;
​
struct Operation {
    char type;
    int x1;
    int y1; 
    int x2;
    int y2;
    Operation(char type, int x1, int y1, int x2, int y2): type(type), x1(x1), y1(y1), x2(x2), y2(y2) {}
    Operation(){};
};
​
int main() {
    int n;
    set<int> x_set, y_set;
    cin >> n;
    vector<Operation> operations(n);
    for (int i = 0; i < n; i++) {
        string type;  // 修复类型为 char
        int x1, y1, x2, y2;
        cin >> type >> x1 >> y1 >> x2 >> y2;  // 正确读取输入
        Operation tmp(type[0], x1, y1, x2, y2);
​
        operations[i] = tmp;  // 将tmp赋值给operations[i]
        x_set.insert(x1);
        x_set.insert(x2);
        y_set.insert(y1);
        y_set.insert(y2);
    }

​
​
    // 离散化
    vector<int> x_coords(x_set.begin(), x_set.end());
    vector<int> y_coords(y_set.begin(), y_set.end());
​
    // 映射坐标值到数组的索引
    auto getIndex = [](int coord, const vector<int>& coords) {
        return lower_bound(coords.begin(), coords.end(), coord) - coords.begin();
    };
​
    // 使用位图来标识整个区域，节省空间
    vector<bitset<MAX_COORD>> grid(y_coords.size());
​
    for (int i = 0; i < operations.size(); i++) {
        Operation p = operations[i];
        int x1 = getIndex(min(p.x1, p.x2), x_coords);
        int x2 = getIndex(max(p.x1, p.x2), x_coords);
        int y1 = getIndex(min(p.y1, p.y2), y_coords);
        int y2 = getIndex(max(p.y1, p.y2), y_coords);

        for (int y = y1; y < y2; y++) {
            if (p.type == 'd') {  // 绘制操作
                for (int x = x1; x < x2; x++) {
                    grid[y].set(x);
                }
            } else {  // 擦除操作
                for (int x = x1; x < x2; x++) {
                    grid[y].reset(x);
                }
            }
        }
    }
​
    // 计算最终面积
    int res = 0;
    for (int y = 0; y < grid.size(); y++) {
        for (int x = 0; x < x_coords.size(); x++) {
            if (grid[y].test(x)) {
                int dx = x_coords[x + 1] - x_coords[x];
                int dy = y_coords[y + 1] - y_coords[y];
                res += dy * dx;
            }
        }
    }
    cout << res;
    return 0;
}
