            this.x1 = x1;
            this.y1 = y1;
            this.x2 = x2;
            this.y2 = y2;
        }
    }
​
    // 映射坐标值到数组的索引
    public static int getIndex(int coord, List<Integer> coords) {
            return Collections.binarySearch(coords, coord);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        Set<Integer> xSet = new TreeSet<>();
        Set<Integer> ySet = new TreeSet<>();
        List<Operation> operations = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String type = scanner.next();
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();

            operations.add(new Operation(type.charAt(0), x1, y1, x2, y2));
            xSet.add(x1);
            xSet.add(x2);
            ySet.add(y1);
            ySet.add(y2);
        }

        // 离散化
        List<Integer> xCoords = new ArrayList<>(xSet);
        List<Integer> yCoords = new ArrayList<>(ySet);

​
​
        // 使用布尔值数组来表示区域
        boolean[][] grid = new boolean[yCoords.size()][xCoords.size()];

        // 遍历操作并修改区域状态
        for (Operation op : operations) {
            int x1 = getIndex(Math.min(op.x1, op.x2), xCoords);
            int x2 = getIndex(Math.max(op.x1, op.x2), xCoords);
            int y1 = getIndex(Math.min(op.y1, op.y2), yCoords);
            int y2 = getIndex(Math.max(op.y1, op.y2), yCoords);

            for (int y = y1; y < y2; y++) {
                for (int x = x1; x < x2; x++) {
                    if (op.type == 'd') {  // 绘制操作
                        grid[y][x] = true;
                    } else {  // 擦除操作
                        grid[y][x] = false;
                    }
                }
            }
        }

        // 计算最终面积
        int res = 0;
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[0].length; x++) {
                if (grid[y][x]) {
                    int dx = xCoords.get(x + 1) - xCoords.get(x);
                    int dy = yCoords.get(y + 1) - yCoords.get(y);
                    res += dy * dx;
                }
            }
        }

        System.out.println(res);
    }
}
