package main
​
import (
    "fmt"
    "sort"
)
​
// 常量，表示坐标的最大值
const MAX_COORD = 201
​
// Operation 结构体表示一个绘制或擦除操作
type Operation struct {
    typ  string // 操作类型（"d"表示绘制，"e"表示擦除）
    x1, y1, x2, y2 int // 矩形的坐标
}
​
func main() {
    // 读取操作数量
    var n int
    fmt.Scan(&n)
​
    // 创建集合用于存储唯一的 x 和 y 坐标
    xSet := make(map[int]struct{})
    ySet := make(map[int]struct{})
    // 存储所有操作
    operations := make([]Operation, n)
​
    // 读取每个操作，并将相关坐标加入集合
    for i := 0; i < n; i++ {
        var typ string
        var x1, y1, x2, y2 int
        fmt.Scan(&typ, &x1, &y1, &x2, &y2)
        operations[i] = Operation{typ, x1, y1, x2, y2}
        xSet[x1] = struct{}{}
        xSet[x2] = struct{}{}
        ySet[y1] = struct{}{}
        ySet[y2] = struct{}{}
    }
​
    // 将 x 和 y 坐标集合转换为有序的切片
    xCoords := make([]int, 0, len(xSet))
    yCoords := make([]int, 0, len(ySet))
    for x := range xSet {
        xCoords = append(xCoords, x)
    }
    for y := range ySet {
        yCoords = append(yCoords, y)
    }
​
    // 排序坐标
    sort.Ints(xCoords)
    sort.Ints(yCoords)
​
    // 获取坐标的索引
    getIndex := func(coord int, coords []int) int {
        // 查找坐标在已排序坐标中的索引
        for i, c := range coords {
            if c == coord {
                return i
            }
        }
        return -1
    }
​
    // 创建二维网格，初始为 false（表示擦除）
    grid := make([][]bool, len(yCoords))
    for i := range grid {
        grid[i] = make([]bool, len(xCoords))
    }
​
    // 处理每个操作
    for _, op := range operations {
        // 获取矩形的索引位置
        x1 := getIndex(min(op.x1, op.x2), xCoords)
        x2 := getIndex(max(op.x1, op.x2), xCoords)
        y1 := getIndex(min(op.y1, op.y2), yCoords)
        y2 := getIndex(max(op.y1, op.y2), yCoords)
​
        // 根据操作类型进行绘制或擦除
        for y := y1; y < y2; y++ {
            for x := x1; x < x2; x++ {
                if op.typ == "d" { // 绘制操作
                    grid[y][x] = true
                } else { // 擦除操作
                    grid[y][x] = false
                }
            }
        }
    }
​
    // 计算最终图形的面积
    var res int
    for y := 0; y < len(grid); y++ {
        for x := 0; x < len(grid[y]); x++ {
            if grid[y][x] {
                // 计算矩形的宽度和高度
                dx := xCoords[x+1] - xCoords[x]
                dy := yCoords[y+1] - yCoords[y]
                // 累加面积
                res += dx * dy
            }
        }
    }
​
    // 输出最终的面积
    fmt.Println(res)
}
​
// 辅助函数：获取两个数中的最小值
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
​
// 辅助函数：获取两个数中的最大值
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
